from pathlib import Path
import pandas as pd,numpy as np,duckdb,json
P=Path(__file__).parent;R=P.parent.parent;Q=Path('/Volumes/ext/minite_k_data');ref=R/'outputs/first_board_1000_study_20261107/industry_reference.parquet';x=pd.read_pickle(P/'全部候选及结果.pkl.gz');paths=[str(Q/'日线/2024.parquet'),str(Q/'日线/2025.parquet')]+[str(p) for p in sorted((Q/'日线').glob('2026-*.parquet')) if p.stem<='2026-06'];c=duckdb.connect();c.execute('SET threads=3');c.execute("SET memory_limit='3GB'")
