for row in z.itertuples():
 if not row.行业可用 or row.d0_date not in reference:ranks.append(np.nan);continue
 codes,values=reference[row.d0_date];other=values[codes!=row.industry_code];p=row.其他同业平均涨幅;ranks.append(float((np.sum(other<p)+.5*np.sum(other==p))/len(other)) if len(other) else np.nan)
z['涨幅排名']=ranks;z['当日行业组']=np.select([z.涨幅排名.isna(),z.涨幅排名.le(1/3),z.涨幅排名.gt(2/3)],['行业未知','较弱三分之一','较强三分之一'],default='行业中间三分之一');z['轮动组']=np.select([z.前五日排名.isna()|z.涨幅排名.isna(),z.前五日排名.le(1/3)&z.涨幅排名.gt(2/3)],['行业未知','前五日较弱且当天较强'],default='其他已知行业');z.to_pickle(P/'带行业全部候选.pkl.gz',compression='gzip')
