  q=d[d.ret.notna()];rows.append({'年份':year,'分组':groupcol,'状态':group,'组合股次':len(d),'可算股次':len(q),'涉及交易日':q.d0_date.nunique(),'上涨股次':int(q.ret.gt(0).sum()),'上涨率%':100*q.ret.gt(0).mean() if len(q) else np.nan,'平均价格收益%':q.ret.mean(),'大跌7%股次':int(q.ret.le(-7).sum()),'大跌7%率%':100*q.ret.le(-7).mean() if len(q) else np.nan})
